    downloadContentPackage: {
        parameters: {
            query: {
                ticket: string;
            };
            header?: {
                /** @description Single byte range, for example `bytes=1048576-`. */
                Range?: string;
            };
            path: {
                versionId: components["parameters"]["VersionId"];
                versionCode: number;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description ZIP archive containing the manifest, versification and book NDJSON files */
            200: {
                headers: {
                    "Cache-Control"?: string;
                    "Accept-Ranges"?: "bytes";
                    "Content-Length"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/zip": string;
                };
            };
            /** @description Partial ZIP archive satisfying a single `Range` request */
            206: {
                headers: {
                    "Content-Range"?: string;
                    "Content-Length"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/zip": string;
                };
            };
            /** @description Ticket is missing, invalid, expired or for another package */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The requested byte range is not satisfiable */
            416: {
                headers: {
                    "Content-Range"?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Package is not published or failed integrity verification */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
